"use server";
import { backendFetch } from "~/lib/backend";

export async function getPresignedUrl(key: string) {
  // Download URLs are generated by the Python backend so AWS credentials never live in Next.js.
  // `key` is already scoped to the authenticated user's media in the existing application.
  const { auth } = await import("~/lib/auth");
  const { headers } = await import("next/headers");
  const { redirect } = await import("next/navigation");
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) redirect("/auth/sign-in");
  return backendFetch<{ url: string }>(session.user.id, "/media/presign-download", {
    method: "POST",
    body: JSON.stringify({ key }),
  });
}
